type qualRemainingKAT struct {
	Records map[string]struct {
		Hex      string
		FieldHex []string `json:"field_hex"`
		Count    int
	}
	Digests   map[string]struct{ Hex string }
	Keys      map[string]string
	LocalBody struct {
		Hex       string
		DigestHex string `json:"digest_hex"`
	} `json:"local_body"`
}

func qualRemainingVectors(t *testing.T) *qualRemainingKAT {
	t.Helper()
	var v qualRemainingKAT
	require.NoError(t, json.Unmarshal([]byte(qualRemainingKATJSON), &v))
	return &v
}
func (v *qualRemainingKAT) record(t *testing.T, n string) []byte {
	t.Helper()
	_, ok := v.Records[n]
	require.True(t, ok, n)
	return qualScopedKATBytes(t, v.Records[n].Hex)
}
func (v *qualRemainingKAT) fields(t *testing.T, n string) [][]byte {
	t.Helper()
	fields := make([][]byte, len(v.Records[n].FieldHex))
	for i, s := range v.Records[n].FieldHex {
		fields[i] = qualScopedKATBytes(t, s)
	}
	return fields
}
func (v *qualRemainingKAT) digest(t *testing.T, n string) []byte {
	t.Helper()
	_, ok := v.Digests[n]
	require.True(t, ok, n)
	return qualScopedKATBytes(t, v.Digests[n].Hex)
}
func (v *qualRemainingKAT) key(t *testing.T, n string) []byte {
	t.Helper()
	_, ok := v.Keys[n]
	require.True(t, ok, n)
	return qualScopedKATBytes(t, v.Keys[n])
}
func qualRemainingCodec(t *testing.T) (*qualNativeStore, *registrationRecords) {
	t.Helper()
	store := qualRegistrationStore(t, 0)
	codec, err := newRegistrationRecords(store, &marshal.GogoProtoMarshalizer{}, blake2b.NewBlake2b(), 4096)
	require.NoError(t, err)
	return store, codec
}

func TestQualDRWARemainingRecordCanonicalKAT(t *testing.T) {
	v := qualRemainingVectors(t)
	_, codec := qualRemainingCodec(t)
	for _, n := range []string{"bootstrap", "association", "activation", "intent_open", "intent_consumed", "projection", "grant_open", "grant_consumed", "grant_closed", "local_pointer", "binding", "progress_pending", "progress_complete", "envelope", "requalification_envelope", "admin_ack"} {
		t.Run(n, func(t *testing.T) {
			expected, fields := v.record(t, n), v.fields(t, n)
			encoded, err := codec.frame(fields...)
			require.NoError(t, err)
			require.Equal(t, expected, encoded)
			decoded, err := codec.unframe(expected, len(fields))
			require.NoError(t, err)
			require.Equal(t, fields, decoded)
			// Independently retained canonical literal is the control for all negatives.
			for _, tc := range []struct {
				name  string
				value []byte
				count int
			}{
				{"unknown-field", append(bytes.Clone(expected), 0x28, 0), len(fields)},
				// Add a redundant zero varint group to the first field length.
				{"overlong-length", qualRemainingOverlong(expected), len(fields)},
				{"truncated", expected[:len(expected)-1], len(fields)},
				{"wrong-count", expected, len(fields) + 1},
			} {
				t.Run(tc.name, func(t *testing.T) { _, err := codec.unframe(tc.value, tc.count); require.Error(t, err) })
			}
		})
	}
}
func qualRemainingOverlong(b []byte) []byte {
	i := 1
	for b[i]&0x80 != 0 {
		i++
	}
	out := bytes.Clone(b[:i])
	out = append(out, b[i]|0x80, 0)
	return append(out, b[i+1:]...)
}

func TestQualDRWARemainingBootstrapOwnerKAT(t *testing.T) {
	v := qualRemainingVectors(t)
	store, codec := qualRemainingCodec(t)
	f := v.fields(t, "bootstrap")
	body := bootstrapIntentBody{networkDomain: f[0], issuer: f[1], programID: f[2], intentNonce: f[3], requestedTokenFamily: f[4], creationProfile: f[5], nameCommitment: f[6], tickerCommitment: f[7], propertyCommitment: f[8], publicSchemaProfile: f[9], issuerProgramAdmissionDecision: f[10], proposedProgramAuthoritySetBodies: [][]byte{[]byte("pa-body"), []byte("sa-body")}, proposedProgramAuthoritySetHashes: [][]byte{codec.hasher.Compute("pa-body"), codec.hasher.Compute("sa-body")}, closurePlan: f[13], networkProfile: f[14], expiry: HeaderMilliseconds(0x0102030405060708)}
	t.Run("body-digests-and-decoder", func(t *testing.T) {
		encoded, digest, id, err := codec.identity(body)
		require.NoError(t, err)
		require.Equal(t, v.record(t, "bootstrap"), encoded)
		require.Equal(t, v.digest(t, "bootstrap_payload"), digest)
		require.Equal(t, v.digest(t, "bootstrap_id"), id)
		decoded, err := codec.decodeBody(v.record(t, "bootstrap"))
		require.NoError(t, err)
		require.Equal(t, body, decoded)
	})
	id := v.digest(t, "bootstrap_id")
	t.Run("native-consumption-and-exact-keys", func(t *testing.T) {
		require.Equal(t, v.key(t, "intent"), append([]byte(registrationIntentPrefix), id...))
		token, manager := []byte("TOKEN-abcdef"), bytes.Repeat([]byte{0x22}, 32)
		require.Equal(t, v.key(t, "association"), append([]byte(registrationAssociationPrefix), token...))
		require.Equal(t, v.key(t, "activation"), append([]byte(registrationActivationPrefix), token...))
		qualRecordPut(t, store, v.key(t, "intent"), v.record(t, "intent_open"))
		current, err := codec.intent(id)
		require.NoError(t, err)
		require.Equal(t, "OPEN", current.status)
		// Seal fixture initialization before creating the exclusive T04 owner.
		_, err = store.Commit()
		require.NoError(t, err)
		r, _ := qualRegistrationOwner(t, store, 2)
		// Existing creation double writes native AccountsDB; not a lawful System-SC registration.
		require.NoError(t, r.registerTokenForIntent(codec, id, v.digest(t, "bootstrap_payload"), manager, qualRegistrationCreator(t, string(token))))
		for _, n := range []string{"association", "activation"} {
			require.Equal(t, v.record(t, n), qualRegistryValue(t, store, string(v.key(t, n))))
		}
		require.Equal(t, v.record(t, "intent_consumed"), qualRegistryValue(t, store, string(v.key(t, "intent"))))
		actual, actualManager, err := codec.registeredToken(token)
		require.NoError(t, err)
		require.Equal(t, "CONSUMED", actual.status)
		require.Equal(t, manager, actualManager)
	})
	for _, name := range []string{"changed-body", "changed-digest", "changed-token"} {
		t.Run(name, func(t *testing.T) {
			token := []byte("TOKEN-abcdef")
			qualRecordPut(t, store, v.key(t, "intent"), v.record(t, "intent_consumed"))
			qualRecordPut(t, store, v.key(t, "association"), v.record(t, "association"))
			_, _, err := codec.registeredToken(token)
			require.NoError(t, err, "healthy retained control")
			fields := v.fields(t, "association")
			index := map[string]int{"changed-body": 3, "changed-digest": 2, "changed-token": 0}[name]
			fields[index][0] ^= 1
			qualRecordPut(t, store, v.key(t, "association"), qualRecordFrame(fields...))
			_, _, err = codec.registeredToken(token)
			require.Error(t, err)
		})
	}
	for _, name := range []string{"short-expiry", "unequal-authority-count"} {
		t.Run(name, func(t *testing.T) {
			fields := v.fields(t, "bootstrap")
			if name == "short-expiry" {
				fields[15] = fields[15][1:]
			} else {
				fields[12] = qualRecordFrame(bytes.Repeat([]byte{1}, 32))
			}
			_, err := codec.decodeBody(qualRecordFrame(fields...))
			require.Error(t, err)
		})
	}
}

func TestQualDRWARemainingGrantOwnerKAT(t *testing.T) {
	v := qualRemainingVectors(t)
	store, codec := qualRemainingCodec(t)
	// This test consumes only the existing codec/retained reader; no admission host.
	r := &sourceGrantRecords{codec: codec}
	p := sourceGrantProjection{token: []byte("TOKEN-abcdef"), source: bytes.Repeat([]byte{0x22}, 32), action: bytes.Repeat([]byte{0x33}, 32), digest: bytes.Repeat([]byte{0x44}, 32), body: []byte("public projection body"), expiry: HeaderMilliseconds(0x0102030405060708)}
	key, projection, err := r.encode(p)
	require.NoError(t, err)
	require.Equal(t, v.key(t, "grant"), key)
	require.Equal(t, v.record(t, "projection"), projection)
	for _, tc := range []struct {
		name, status, reason string
		effect               []byte
	}{
		{"grant_open", "OPEN", "", nil}, {"grant_consumed", "CONSUMED", "", bytes.Repeat([]byte{0x55}, 32)}, {"grant_closed", "CLOSED_UNUSED", "STALE_BINDING", nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			qualRecordPut(t, store, key, v.record(t, tc.name))
			status, reason, effect, err := r.load(key, projection)
			require.NoError(t, err)
			require.Equal(t, tc.status, status)
			require.Equal(t, tc.reason, reason)
			require.Equal(t, len(tc.effect), len(effect))
			require.True(t, bytes.Equal(tc.effect, effect))
			require.NoError(t, r.save(key, projection, tc.status, tc.reason, tc.effect))
			require.Equal(t, v.record(t, tc.name), qualRegistryValue(t, store, string(key)))
		})
	}
	for _, tc := range []struct {
		name, status, reason string
		effect               []byte
	}{
		{"unknown-status", "UNKNOWN", "", nil}, {"open-reason", "OPEN", "EXPIRED", nil}, {"open-effect", "OPEN", "", bytes.Repeat([]byte{1}, 32)},
		{"consumed-short-effect", "CONSUMED", "", []byte{1}}, {"consumed-reason", "CONSUMED", "EXPIRED", bytes.Repeat([]byte{1}, 32)},
		{"closed-reason", "CLOSED_UNUSED", "UNKNOWN", nil}, {"closed-effect", "CLOSED_UNUSED", "EXPIRED", []byte{1}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			qualRecordPut(t, store, key, v.record(t, "grant_open"))
			_, _, _, err := r.load(key, projection)
			require.NoError(t, err)
			qualRecordPut(t, store, key, qualRecordFrame(projection, []byte(tc.status), []byte(tc.reason), tc.effect))
			_, _, _, err = r.load(key, projection)
			require.Error(t, err)
		})
	}
}

func TestQualDRWARemainingConvergenceOwnerKAT(t *testing.T) {
	v := qualRemainingVectors(t)
	store, codec := qualRemainingCodec(t)
	r := &convergenceRecords{codec: codec, maxShards: 3}
	tr := convergenceTransition{action: bytes.Repeat([]byte{0x33}, 32), digest: bytes.Repeat([]byte{0x44}, 32), token: []byte("TOKEN-abcdef"), target: bytes.Repeat([]byte{0x55}, 32), dependencies: bytes.Repeat([]byte{0x66}, 32), requiredSet: v.digest(t, "required_set"), version: 7, shards: []uint32{0, 1, 2}}
	key, binding, err := r.encode(tr)
	require.NoError(t, err)
	require.Equal(t, v.key(t, "convergence"), key)
	require.Equal(t, v.record(t, "binding"), binding)
	for _, name := range []string{"pending", "complete"} {
		t.Run(name, func(t *testing.T) {
			p := &convergenceProgress{status: "PENDING", bitmap: []byte{0}, acks: make([][]byte, 3)}
			if name == "complete" {
				p.status = "COMPLETE"
				p.bitmap[0] = 7
				for i := range p.acks {
					p.acks[i] = v.digest(t, []string{"ack0", "ack1", "ack2"}[i])
				}
			}
			value, err := r.value(binding, p)
			require.NoError(t, err)
			require.Equal(t, v.record(t, "progress_"+name), value)
			require.Equal(t, v.digest(t, name+"_commitment"), p.commitment)
			qualRecordPut(t, store, key, value)
			loaded, err := r.load(key, binding, 3)
			require.NoError(t, err)
			require.Equal(t, p.status, loaded.status)
			require.Equal(t, p.bitmap, loaded.bitmap)
			require.Equal(t, p.commitment, loaded.commitment)
		})
	}
	for _, name := range []string{"changed-commitment", "padding-bit", "missing-credited-slot"} {
		t.Run(name, func(t *testing.T) {
			qualRecordPut(t, store, key, v.record(t, "progress_complete"))
			_, err := r.load(key, binding, 3)
			require.NoError(t, err)
			fields := v.fields(t, "progress_complete")
			switch name {
			case "changed-commitment":
				fields[4][0] ^= 1
			case "padding-bit":
				fields[2][0] |= 0x80
			case "missing-credited-slot":
				fields[3] = qualRecordFrame(nil, v.digest(t, "ack1"), v.digest(t, "ack2"))
			}
			qualRecordPut(t, store, key, qualRecordFrame(fields...))
			_, err = r.load(key, binding, 3)
			require.Error(t, err)
		})
	}
}

func TestQualDRWARemainingAdminOwnerKAT(t *testing.T) {
	v := qualRemainingVectors(t)
	_, codec := qualRemainingCodec(t)
	c := &adminCarrier{codec: codec, domain: []byte("fixture-domain")}
	e := adminEffectEnvelope{effectID: bytes.Repeat([]byte{0x33}, 32), legID: bytes.Repeat([]byte{0x44}, 32), operation: []byte("DRWAApplyTokenAdmin"), origin: bytes.Repeat([]byte{0x55}, 32), openCommitment: bytes.Repeat([]byte{0x66}, 32), tokenID: []byte("TOKEN-abcdef"), tokenType: []byte(core.FungibleESDT), binding: []byte("CURRENT_CEB"), cebEpoch: 7, normalizedDigest: v.digest(t, "admin_normalized"), discriminator: []byte("ESDTFreeze"), payload: []byte("ESDTFreeze@544f4b454e2d616263646566"), targetShard: 1, targetKey: []byte("public-target-key"), predecessor: bytes.Repeat([]byte{0x88}, 32), result: bytes.Repeat([]byte{0x99}, 32), gasVersion: []byte("public-schedule"), workLimit: 9}
	e.actionID, e.planDigest, e.planStep = []byte{}, []byte{}, []byte{}
	for _, name := range []string{"envelope", "requalification_envelope"} {
		t.Run(name, func(t *testing.T) {
			current := e.copy()
			if name == "requalification_envelope" {
				current.operation = []byte("DRWAApplyRequalificationAdmin")
				current.binding = []byte("PREPARED_CEB")
				current.actionID = bytes.Repeat([]byte{0x33}, 32)
				current.planDigest = bytes.Repeat([]byte{0x44}, 32)
				current.planStep = make([]byte, 8)
			}
			value, err := c.encode(current)
			require.NoError(t, err)
			require.Equal(t, v.record(t, name), value)
			decoded, err := c.decode(v.record(t, name))
			require.NoError(t, err)
			require.Equal(t, current, decoded)
		})
	}
	t.Run("normalized-digest-key-and-ack", func(t *testing.T) {
		normalized, err := c.normalized(e.payload, e.discriminator)
		require.NoError(t, err)
		require.Equal(t, v.digest(t, "admin_normalized"), normalized)
		id, err := c.digest("APPLIED_ID", e.effectID, e.legID)
		require.NoError(t, err)
		require.Equal(t, v.digest(t, "admin_applied"), id)
		require.Equal(t, v.key(t, "admin_applied"), append([]byte(adminAppliedPrefix), id...))
		ack, err := codec.frame([]byte("DRWA/ADMIN_ACK/candidate1"), v.record(t, "envelope"))
		require.NoError(t, err)
		require.Equal(t, v.record(t, "admin_ack"), ack)
	})
	for _, name := range []string{"wrong-domain", "present-step-without-plan", "changed-normalized-digest"} {
		t.Run(name, func(t *testing.T) {
			_, err := c.decode(v.record(t, "envelope"))
			require.NoError(t, err)
			fields := v.fields(t, "envelope")
			switch name {
			case "wrong-domain":
				fields[1] = []byte("other-domain")
			case "present-step-without-plan":
				fields[13] = make([]byte, 8)
			case "changed-normalized-digest":
				fields[14][0] ^= 1
			}
			_, err = c.decode(qualRecordFrame(fields...))
			require.Error(t, err)
		})
	}
}

func TestQualDRWARemainingLocalPointerOwnerKAT(t *testing.T) {
	v := qualRemainingVectors(t)
	f := qualCurrentLocalNew(t)
	f.body = qualScopedKATBytes(t, v.LocalBody.Hex)
	f.host.body = bytes.Clone(f.body)
	f.hash = qualScopedKATBytes(t, v.LocalBody.DigestHex)
	f.pointer = v.record(t, "local_pointer")
	f.pointerKey = v.key(t, "local_pointer")
	f.bodyKey = v.key(t, "local_body")
	qualRecordPut(t, f.store, f.pointerKey, f.pointer)
	qualRecordPut(t, f.store, f.bodyKey, f.body)
	t.Run("native-reader-and-exact-keys", func(t *testing.T) {
		key, err := f.r.codec.frame(f.token)
		require.NoError(t, err)
		require.Equal(t, f.pointerKey, append([]byte(currentLocalPointerPrefix), key...))
		identity, err := f.r.codec.frame(f.token, []byte{0, 0, 0, 0, 0, 0, 0, 7})
		require.NoError(t, err)
		require.Equal(t, f.bodyKey, append([]byte(currentLocalBodyPrefix), identity...))
		before := f.store.JournalLen()
		view, err := f.resolve()
		require.NoError(t, err)
		require.Equal(t, f.pointer, view.pointer)
		require.Equal(t, f.body, view.body)
		require.Equal(t, before, f.store.JournalLen())
	})
	t.Run("short-epoch", func(t *testing.T) {
		_, err := f.resolve()
		require.NoError(t, err)
		fields := v.fields(t, "local_pointer")
		fields[0] = fields[0][1:]
		qualRecordPut(t, f.store, f.pointerKey, qualRecordFrame(fields...))
		_, err = f.resolve()
		require.Error(t, err)
	})
}
